with kept_keys as (select city, segment from customers intersect all select city, segment from customers where lower(name) like '%avi%'), kept_rows as (select s.* from customers s inner join kept_keys k on s.city = k.city and s.segment = k.segment) select case when age >= 61 then 'HIGH' else 'LOW' end as age_tier, date_trunc('quarter', signup_date) as quarter_start, percentile_approx(age, 0.95) as age_p95, count_if(city = 'Chiang Mai') as chiang_mai_events, corr(age, credit_limit) as corr_age_credit_limit, count(*) as event_count, approx_percentile(age, array(0.25, 0.5, 0.75)) as age_quartiles, stddev_samp(age) as age_stddev from kept_rows group by grouping sets ((case when age >= 61 then 'HIGH' else 'LOW' end, date_trunc('quarter', signup_date)), (case when age >= 61 then 'HIGH' else 'LOW' end), ()) order by event_count desc nulls last;
